static int g_failed = 0;

static void expectNear(float actual, float expected, float tol, const char *label) {
  float error = std::fabs(actual - expected);
  if (!std::isfinite(actual) || error > tol) {
    g_failed++;
    std::printf("FAIL %s (actual=%.6f expected=%.6f tol=%.6f)\n", label, actual, expected, tol);
  }
}

int main() {
  std::printf("XYZgeomag Unit Tests (WMM2025)\n");

  for (size_t i = 0; i < sizeof(kGeomagCases) / sizeof(kGeomagCases[0]); ++i) {
    const auto &tc = kGeomagCases[i];
    geomag::Elements out = geomag::magField2Elements(
        geomag::GeoMag(tc.year, geomag::geodetic2ecef(tc.lat, tc.lon, tc.alt_km * 1000.0f), geomag::WMM2025),
        tc.lat, tc.lon);
    std::printf("\nGeomag case %zu: lat=%.6f lon=%.6f alt=%.2fkm year=%.3f\n", i + 1, tc.lat, tc.lon, tc.alt_km, tc.year);
    expectNear(out.north, tc.expected_X, 0.1f, "north");
    expectNear(out.east, tc.expected_Y, 0.1f, "east");
    expectNear(out.down, tc.expected_Z, 0.1f, "down");
    expectNear(out.horizontal, tc.expected_H, 0.1f, "horizontal");
    expectNear(out.total, tc.expected_F, 0.1f, "total");
    expectNear(out.inclination, tc.expected_inc, 0.01f, "inclination");
    expectNear(out.declination, tc.expected_dec, 0.01f, "declination");
  }

  std::printf("\nXYZgeomag: %s\n", g_failed == 0 ? "PASS" : "FAIL");
  return g_failed == 0 ? 0 : 1;
}
